@Test
public void upgradeToVersionShouldThrowOnMissingVersion() {
    Map<SchemaVersion, Migration> allMigrationClazz = ImmutableMap.<SchemaVersion, Migration>builder().put(OLDER_VERSION, successfulMigration).put(LATEST_VERSION, successfulMigration).build();
    testee = new CassandraMigrationService(schemaVersionDAO, allMigrationClazz, LATEST_VERSION);
    when(schemaVersionDAO.getCurrentSchemaVersion()).thenReturn(CompletableFuture.completedFuture(Optional.of(OLDER_VERSION)));
