@Test
public void searchShouldOrderByInternalDateWhenSortOnSentDateAndNoCorrespondingHeader() throws Exception {
    MailboxPath mailboxPath = MailboxPath.forUser(USERNAME, "sentDate");
    storeMailboxManager.createMailbox(mailboxPath, session);
    MessageManager messageManager = storeMailboxManager.getMailbox(mailboxPath, session);
    SimpleDateFormat simpleDateFormat = new SimpleDateFormat("yyyy-MM-dd");
    Date date1 = simpleDateFormat.parse("2017-08-24");
    Date date2 = simpleDateFormat.parse("2017-08-23");
    Date date3 = simpleDateFormat.parse("2017-08-25");
    ComposedMessageId message1 = messageManager.appendMessage(MessageManager.AppendCommand.builder().withInternalDate(date1).build(Message.Builder.of().setSubject("test").setBody("testmail", StandardCharsets.UTF_8)), session);
    ComposedMessageId message2 = messageManager.appendMessage(MessageManager.AppendCommand.builder().withInternalDate(date2).build(Message.Builder.of().setSubject("test").setBody("testmail", StandardCharsets.UTF_8)), session);
    ComposedMessageId message3 = messageManager.appendMessage(MessageManager.AppendCommand.builder().withInternalDate(date3).build(Message.Builder.of().setSubject("test").setBody("testmail", StandardCharsets.UTF_8)), session);
    await();
    SearchQuery searchQuery = new SearchQuery();
    searchQuery.setSorts(ImmutableList.of(new Sort(SortClause.SentDate)));
    assertThat(messageManager.search(searchQuery, session)).containsExactly(message2.getUid(), message1.getUid(), message3.getUid());
}

@Test
public void searchShouldOrderBySentDateThenInternalDateWhenSortOnSentDateAndNonHomogeneousCorrespondingHeader() throws Exception {
    MailboxPath mailboxPath = MailboxPath.forUser(USERNAME, "sentDate");
    storeMailboxManager.createMailbox(mailboxPath, session);
    MessageManager messageManager = storeMailboxManager.getMailbox(mailboxPath, session);
    SimpleDateFormat simpleDateFormat = new SimpleDateFormat("yyyy-MM-dd");
    Date date1 = simpleDateFormat.parse("2017-08-24");
    Date date2 = simpleDateFormat.parse("2017-08-26");
    Date date3 = simpleDateFormat.parse("2017-08-25");
    ComposedMessageId message1 = messageManager.appendMessage(MessageManager.AppendCommand.builder().withInternalDate(date1).build(Message.Builder.of().setSubject("test").setBody("testmail", StandardCharsets.UTF_8)), session);
    ComposedMessageId message2 = messageManager.appendMessage(MessageManager.AppendCommand.builder().withInternalDate(date2).build(Message.Builder.of().setSubject("test").setDate(new SimpleDateFormat("yyyy/MM/dd HH:mm:ss").parse("2017/08/23 00:00:00 "), TimeZone.getTimeZone(ZoneId.of("+0200"))).setBody("testmail", StandardCharsets.UTF_8)), session);
    ComposedMessageId message3 = messageManager.appendMessage(MessageManager.AppendCommand.builder().withInternalDate(date3).build(Message.Builder.of().setSubject("test").setBody("testmail", StandardCharsets.UTF_8)), session);
    await();
    SearchQuery searchQuery = new SearchQuery();
    searchQuery.setSorts(ImmutableList.of(new Sort(SortClause.SentDate)));
    assertThat(messageManager.search(searchQuery, session)).containsExactly(message2.getUid(), message1.getUid(), message3.getUid());
}

