    builder.setFlags(true, false, true, true, true, true);
    MailboxMessage row = builder.build();
    recent.add(row.getUid());
    assertFalse(messageSearches.isMatch(SearchQuery.flagIsUnSet(Flags.Flag.SEEN), row, recent));
    assertTrue(messageSearches.isMatch(SearchQuery.flagIsUnSet(Flags.Flag.FLAGGED), row, recent));
    assertFalse(messageSearches.isMatch(SearchQuery.flagIsUnSet(Flags.Flag.ANSWERED), row, recent));
    assertFalse(messageSearches.isMatch(SearchQuery.flagIsUnSet(Flags.Flag.DRAFT), row, recent));
    assertFalse(messageSearches.isMatch(SearchQuery.flagIsUnSet(Flags.Flag.DELETED), row, recent));
    assertFalse(messageSearches.isMatch(SearchQuery.flagIsUnSet(Flags.Flag.RECENT), row, recent));
}

