    assertEquals(Calendar.APRIL, DecoderUtils.decodeMonth('A', 'P', 'R'));
    assertEquals(Calendar.APRIL, DecoderUtils.decodeMonth('a', 'p', 'r'));
    assertEquals(Calendar.MAY, DecoderUtils.decodeMonth('M', 'A', 'Y'));
