@Test
public void chainAllShouldPreserveExecutionOrder() {
    int itemCount = 10;
    ImmutableList<Integer> ints = IntStream.range(0, itemCount).boxed().collect(Guavate.toImmutableList());
    ConcurrentLinkedDeque<Integer> queue = new ConcurrentLinkedDeque<>();
    CompletableFutureUtil.chainAll(ints.stream(), i -> CompletableFuture.supplyAsync(() -> {
        try {
            Thread.sleep(itemCount - i);
        } catch (InterruptedException e) {
            throw Throwables.propagate(e);
        }
        queue.add(i);
        return i;
    }, executorService)).join();
    assertThat(queue).containsExactlyElementsOf(ints);
}

