    when(dnsService.getLocalHost()).thenReturn(InetAddress.getByName("127.0.0.1"));
    when(dnsService.getHostName(any(InetAddress.class))).thenReturn(detected);
    InetAddress detectedAddress1 = mock(InetAddress.class);
