    String content = "MIME-Version: 1.0\r\n" + "Cc: =?UTF-8?Q?=F0=9F=9A=B2@linagora.com?=\r\n" + "Content-Type: text/plain; charset=utf-8\r\n" + "\r\n" + "test\r\n";
    FakeMail mail = FakeMail.from(MimeMessageUtil.mimeMessageFromString(content));
    String generateMessage = new NotifyMailetsMessage().generateMessage("my message", mail);
    assertThat(generateMessage).contains("  CC: \n" + "🚲@linagora.com");
}

