    when(automaticallySentMailDetector.isAutomaticallySent(mail)).thenReturn(false);
    when(notificationRegistry.isRegistered(ACCOUNT_ID, RecipientId.fromMailAddress(originalSender))).thenReturn(CompletableFuture.completedFuture(false));
