public void convertToMimeShouldAddAttachmentWhenOne() {
    // Given
    MIMEMessageConverter sut = new MIMEMessageConverter();
    CreationMessage testMessage = CreationMessage.builder().mailboxId("dead-bada55").subject("subject").from(DraftEmailer.builder().name("sender").build()).htmlBody("Hello <b>all<b>!").build();
    String expectedCID = "cid";
    String expectedMimeType = "image/png";
    String text = "123456";
    TextBody expectedBody = new BasicBodyFactory().textBody(text.getBytes(), StandardCharsets.UTF_8);
    MessageAttachment attachment = MessageAttachment.builder().attachment(org.apache.james.mailbox.model.Attachment.builder().attachmentId(AttachmentId.from("blodId")).bytes(text.getBytes()).type(expectedMimeType).build()).cid(Cid.from(expectedCID)).isInline(true).build();
    // When
    Message result = sut.convertToMime(new ValueWithId.CreationMessageEntry(CreationMessageId.of("user|mailbox|1"), testMessage), ImmutableList.of(attachment));
    // Then
    assertThat(result.getBody()).isInstanceOf(Multipart.class);
    assertThat(result.isMultipart()).isTrue();
    Multipart typedResult = (Multipart) result.getBody();
    assertThat(typedResult.getBodyParts()).hasSize(2);
