public void generateMDNMessageShouldUseDispositionHeaders() throws Exception {
    String senderAddress = "sender@local";
    Message originMessage = Message.Builder.of().setMessageId("45554@local.com").setFrom(senderAddress).setBody("body", StandardCharsets.UTF_8).addField(new RawField(JmapMDN.RETURN_PATH, "<" + senderAddress + ">")).addField(new RawField(JmapMDN.DISPOSITION_NOTIFICATION_TO, "<" + senderAddress + ">")).build();
