    MetaDataWithContent testMail = MetaDataWithContent.builder().uid(MessageUid.of(2)).keywords(keywords).size(headers.length()).internalDate(INTERNAL_DATE).content(new ByteArrayInputStream(headers.getBytes(StandardCharsets.UTF_8))).attachments(ImmutableList.of()).mailboxId(MAILBOX_ID).messageId(TestMessageId.of(2)).build();
