@Test
public void buildShouldWorkWhenAllFieldsArePresent() {
    Emailer from = Emailer.builder().name("from").email("from@domain").build();
    ImmutableList<Emailer> to = ImmutableList.of(Emailer.builder().name("to").email("to@domain").build());
    ImmutableList<Emailer> cc = ImmutableList.of(Emailer.builder().name("cc").email("cc@domain").build());
    ImmutableList<Emailer> bcc = ImmutableList.of(Emailer.builder().name("bcc").email("bcc@domain").build());
    ImmutableList<Emailer> replyTo = ImmutableList.of(Emailer.builder().name("replyTo").email("replyTo@domain").build());
    Instant currentDate = Instant.now();
    Attachment simpleAttachment = Attachment.builder().blobId(BlobId.of("blobId")).type("type").name("name").size(123).build();
    ImmutableList<Attachment> attachments = ImmutableList.of(simpleAttachment);
    SubMessage simpleMessage = SubMessage.builder().headers(ImmutableMap.of("key", "value")).subject("subject").date(currentDate).build();
    ImmutableMap<BlobId, SubMessage> attachedMessages = ImmutableMap.of(BlobId.of("blobId"), simpleMessage);
    Keywords keywords = Keywords.factory().from(Keyword.DRAFT, Keyword.ANSWERED, Keyword.FLAGGED);
    Number messageSize = Number.fromLong(123);
    Message expected = new Message(TestMessageId.of(1), BlobId.of("blobId"), "threadId", ImmutableList.of(InMemoryId.of(456)), Optional.of("inReplyToMessageId"), true, ImmutableMap.of("key", "value"), Optional.of(from), to, cc, bcc, replyTo, "subject", currentDate, messageSize, "preview", Optional.of("textBody"), Optional.of("htmlBody"), attachments, attachedMessages, keywords);
    Message tested = Message.builder().id(TestMessageId.of(1)).blobId(BlobId.of("blobId")).threadId("threadId").mailboxId(InMemoryId.of(456)).inReplyToMessageId("inReplyToMessageId").keywords(keywords).headers(ImmutableMap.of("key", "value")).from(from).to(to).cc(cc).bcc(bcc).replyTo(replyTo).subject("subject").date(currentDate).size(123).preview("preview").textBody(Optional.of("textBody")).htmlBody(Optional.of("htmlBody")).attachments(attachments).attachedMessages(attachedMessages).build();
    assertThat(tested).isEqualToComparingFieldByField(expected);
}

