    given().header("Authorization", bobAccessToken.serialize()).body("[[\"getMessageList\", {}, \"#0\"]]").when().post("/jmap").then().log().ifValidationFails().statusCode(200).body(NAME, equalTo("messageList")).body(ARGUMENTS + ".messageIds", hasSize(1));
}

