@Test
public void shouldSendANoticeWhenThresholdExceeded() throws Exception {
    jmapServer.getProbe(QuotaProbesImpl.class).setMaxStorage(MailboxConstants.USER_NAMESPACE + "&" + HOMER, new SerializableQuotaValue<>(QuotaSize.size(100 * 1000)));
    bartSendMessageToHomer();
    // Homer receives a mail big enough to trigger a configured threshold
    calmlyAwait.atMost(30, TimeUnit.SECONDS).until(() -> listMessageIdsForAccount(homerAccessToken).size() == 2);
