    String requestBody = "[" + "  [" + "    \"setMessages\"," + "    {" + "      \"create\": { \"" + messageCreationId + "\" : {" + "        \"from\": { \"name\": \"Me\", \"email\": \"" + fromAddress + "\"}," + "        \"to\": [{ \"name\": \"BOB\", \"email\": \"someone@example.com\"}]," + "        \"subject\": \"Thank you for joining example.com!\"," + "        \"textBody\": \"Hello someone, and thank you for joining example.com!\"," + "        \"mailboxIds\": [\"" + getOutboxId(accessToken) + "\"]" + "      }}" + "    }," + "    \"#0\"" + "  ]" + "]";
