        mailboxManager.createMailbox(mailboxPath, session);
    }
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    out.write(content);
    byte[] bigMail = new byte[1024 * 1024 * 10];
    int c = 0;
    for (int i = 0; i < bigMail.length; i++) {
        bigMail[i] = 'X';
        c++;
        if (c == 1000 || i + 3 == bigMail.length) {
            c = 0;
            bigMail[++i] = '\r';
            bigMail[++i] = '\n';
        }
    }
    out.write(bigMail);
