    assertThat(smtpProtocol.getReplyCode()).as("authenticated").isEqualTo(235);
    smtpProtocol.addRecipient("mail@sample.com");
    assertThat(smtpProtocol.getReplyCode()).as("authenticated.. not reject").isEqualTo(250);
    smtpProtocol.sendShortMessageData("Subject: test\r\n\r\nTest body testDNSRBLNotRejectAuthUser\r\n");
