@Test
public void testPipelining() throws Exception {
    StringBuilder buf = new StringBuilder();
    init(smtpConfiguration);
    InetSocketAddress bindedAddress = new ProtocolServerUtils(smtpServer).retrieveBindedAddress();
    Socket client = new Socket(bindedAddress.getAddress().getHostAddress(), bindedAddress.getPort());
    buf.append("HELO TEST");
    buf.append("\r\n");
    buf.append("MAIL FROM: <test@localhost>");
    buf.append("\r\n");
    buf.append("RCPT TO: <test2@localhost>");
    buf.append("\r\n");
    buf.append("DATA");
    buf.append("\r\n");
    buf.append("Subject: test");
    buf.append("\r\n");
    buf.append("\r\n");
    buf.append("content");
    buf.append("\r\n");
    buf.append(".");
    buf.append("\r\n");
    buf.append("quit");
    buf.append("\r\n");
    OutputStream out = client.getOutputStream();
    out.write(buf.toString().getBytes());
    out.flush();
    BufferedReader in = new BufferedReader(new InputStreamReader(client.getInputStream()));
    assertThat(Integer.parseInt(in.readLine().split(" ")[0])).as("Connection made").isEqualTo(220);
    assertThat(Integer.parseInt(in.readLine().split(" ")[0])).as("HELO accepted").isEqualTo(250);
    assertThat(Integer.parseInt(in.readLine().split(" ")[0])).as("MAIL FROM accepted").isEqualTo(250);
    assertThat(Integer.parseInt(in.readLine().split(" ")[0])).as("RCPT TO accepted").isEqualTo(250);
    assertThat(Integer.parseInt(in.readLine().split(" ")[0])).as("DATA accepted").isEqualTo(354);
    assertThat(Integer.parseInt(in.readLine().split(" ")[0])).as("Message accepted").isEqualTo(250);
    in.close();
    out.close();
    client.close();
}

