@Test
default void priorityShouldReorderMailsWhenDequeing() throws Exception {
    getMailQueue().enQueue(defaultMail().name("name3").attribute(MailPrioritySupport.MAIL_PRIORITY, 3).build());
    getMailQueue().enQueue(defaultMail().name("name9").attribute(MailPrioritySupport.MAIL_PRIORITY, 9).build());
    getMailQueue().enQueue(defaultMail().name("name1").attribute(MailPrioritySupport.MAIL_PRIORITY, 1).build());
    getMailQueue().enQueue(defaultMail().name("name8").attribute(MailPrioritySupport.MAIL_PRIORITY, 8).build());
    getMailQueue().enQueue(defaultMail().name("name6").attribute(MailPrioritySupport.MAIL_PRIORITY, 6).build());
    getMailQueue().enQueue(defaultMail().name("name0").attribute(MailPrioritySupport.MAIL_PRIORITY, 0).build());
    getMailQueue().enQueue(defaultMail().name("name7").attribute(MailPrioritySupport.MAIL_PRIORITY, 7).build());
    getMailQueue().enQueue(defaultMail().name("name4").attribute(MailPrioritySupport.MAIL_PRIORITY, 4).build());
    getMailQueue().enQueue(defaultMail().name("name2").attribute(MailPrioritySupport.MAIL_PRIORITY, 2).build());
    getMailQueue().enQueue(defaultMail().name("name5").attribute(MailPrioritySupport.MAIL_PRIORITY, 5).build());
    ImmutableList<MailQueue.MailQueueItem> items = IntStream.range(1, 11).boxed().map(Throwing.function(i -> {
        MailQueue.MailQueueItem item = getMailQueue().deQueue();
        item.done(true);
        return item;
    })).collect(Guavate.toImmutableList());
    assertThat(items).extracting(MailQueue.MailQueueItem::getMail).extracting(Mail::getName).containsExactly("name9", "name8", "name7", "name6", "name5", "name4", "name3", "name2", "name1", "name0");
}

