@Test
public void listShouldReturnTaskSatus() throws Exception {
    CountDownLatch latch1 = new CountDownLatch(1);
    CountDownLatch latch2 = new CountDownLatch(1);
    CountDownLatch latch3 = new CountDownLatch(1);
    TaskId failedId = memoryTaskManager.submit(() -> Task.Result.PARTIAL);
    TaskId successfulId = memoryTaskManager.submit(() -> Task.Result.COMPLETED);
    TaskId inProgressId = memoryTaskManager.submit(() -> {
        await(latch1);
        latch2.countDown();
        await(latch3);
        return Task.Result.COMPLETED;
    });
    TaskId waitingId = memoryTaskManager.submit(() -> {
        await(latch3);
        latch2.countDown();
        return Task.Result.COMPLETED;
    });
    latch1.countDown();
    latch2.await();
    List<TaskExecutionDetails> list = memoryTaskManager.list();
    softly.assertThat(list).hasSize(4);
    softly.assertThat(entryWithId(list, failedId)).isEqualTo(TaskManager.Status.FAILED);
    softly.assertThat(entryWithId(list, waitingId)).isEqualTo(TaskManager.Status.WAITING);
    softly.assertThat(entryWithId(list, successfulId)).isEqualTo(TaskManager.Status.COMPLETED);
    softly.assertThat(entryWithId(list, inProgressId)).isEqualTo(TaskManager.Status.IN_PROGRESS);
}

