public void learnAsHamShouldAllowToForgetSpam() throws Exception {
    MimeMessage mimeMessage = MimeMessageUtil.mimeMessageFromStream(ClassLoader.getSystemResourceAsStream("eml/spam.eml"));
    byte[] messageAsBytes = MimeMessageUtil.asString(mimeMessage).getBytes(StandardCharsets.UTF_8);
    testee.learnAsSpam(new ByteArrayInputStream(messageAsBytes), USER);
    testee.learnAsHam(new ByteArrayInputStream(messageAsBytes), USER);
    SpamAssassinResult result = testee.scanMail(mimeMessage, USER);
    assertThat(result.getHeadersAsAttribute().get(SpamAssassinResult.FLAG_MAIL_ATTRIBUTE_NAME)).isEqualTo("NO");
}

@Test
public void buildShouldThrowWhenHitsIsNotGiven() {
    assertThatThrownBy(() -> SpamAssassinResult.asSpam().requiredHits("4.0").build()).isInstanceOf(NullPointerException.class);
}

@Test
public void buildShouldThrowWhenRequiredHitsIsNotGiven() {
    assertThatThrownBy(() -> SpamAssassinResult.asSpam().hits("4.0").build()).isInstanceOf(NullPointerException.class);
}

@Test
public void buildShouldWork() {
    String hits = "1.1";
    String requiredHits = "5.0";
    SpamAssassinResult spamAssassinResult = SpamAssassinResult.asSpam().hits(hits).requiredHits(requiredHits).build();
    softly.assertThat(spamAssassinResult.getHits()).isEqualTo(hits);
    softly.assertThat(spamAssassinResult.getRequiredHits()).isEqualTo(requiredHits);
    softly.assertThat(spamAssassinResult.getHeadersAsAttribute()).containsAllEntriesOf(ImmutableMap.of(SpamAssassinResult.FLAG_MAIL_ATTRIBUTE_NAME, "YES", SpamAssassinResult.STATUS_MAIL_ATTRIBUTE_NAME, "Yes, hits=1.1 required=5.0"));
}

@Test
public void headersAsAttributeShouldContainSpamHeaderWithYESValueWhenBuiltAsSpam() {
    String hits = "1.1";
    String requiredHits = "5.0";
    SpamAssassinResult spamAssassinResult = SpamAssassinResult.asSpam().hits(hits).requiredHits(requiredHits).build();
    assertThat(spamAssassinResult.getHeadersAsAttribute()).containsEntry(SpamAssassinResult.FLAG_MAIL_ATTRIBUTE_NAME, "YES");
}

@Test
public void headersAsAttributeShouldContainSpamHeaderWithNOValueWhenBuiltAsHam() {
    String hits = "1.1";
    String requiredHits = "5.0";
    SpamAssassinResult spamAssassinResult = SpamAssassinResult.asHam().hits(hits).requiredHits(requiredHits).build();
    assertThat(spamAssassinResult.getHeadersAsAttribute()).containsEntry(SpamAssassinResult.FLAG_MAIL_ATTRIBUTE_NAME, "NO");
}
